import copy


def _decode_token(token):
    """Decode a JSON Pointer reference token (~1 → /, ~0 → ~).

    Raises ValueError on invalid escape sequences.
    """
    result = []
    i = 0
    while i < len(token):
        if token[i] == '~':
            if i + 1 >= len(token):
                raise ValueError(
                    f"Invalid escape: trailing '~' in reference token {token!r}"
                )
            nxt = token[i + 1]
            if nxt == '0':
                result.append('~')
            elif nxt == '1':
                result.append('/')
            else:
                raise ValueError(
                    f"Invalid escape '~{nxt}' in reference token {token!r}"
                )
            i += 2
        else:
            result.append(token[i])
            i += 1
    return ''.join(result)


def _parse_path(path):
    """Validate a JSON Pointer path for a top-level key and return the decoded key.

    Raises ValueError if the path is malformed, has an invalid escape,
    or addresses a nested location.
    """
    if not isinstance(path, str):
        raise ValueError(f"Path must be a string, got {type(path).__name__}")
    if not path.startswith('/'):
        raise ValueError(f"Path must start with '/', got {path!r}")

    rest = path[1:]
    tokens = rest.split('/')

    if len(tokens) != 1:
        raise ValueError(
            f"Only top-level keys are supported; nested path {path!r} is not allowed"
        )

    return _decode_token(tokens[0])


def apply_patch(document, operations):
    """Apply a list of patch operations to a top-level JSON object.

    Supported operations: add, replace, remove, test.
    Returns a deep copy of the patched document.  Never mutates
    *document*, *operations*, or any nested value.
    """
    if not isinstance(document, dict):
        raise ValueError("Document must be a JSON object (dict)")
    if not isinstance(operations, list):
        raise ValueError("Operations must be a list")

    result = copy.deepcopy(document)

    for op_obj in operations:
        if not isinstance(op_obj, dict):
            raise ValueError(
                f"Each operation must be an object, got {type(op_obj).__name__}"
            )
        if 'op' not in op_obj:
            raise ValueError("Operation missing required field 'op'")
        if 'path' not in op_obj:
            raise ValueError("Operation missing required field 'path'")

        op_type = op_obj['op']
        if op_type not in ('add', 'replace', 'remove', 'test'):
            raise ValueError(f"Invalid operation: {op_type!r}")

        key = _parse_path(op_obj['path'])

        if op_type == 'add':
            if 'value' not in op_obj:
                raise ValueError("'add' operation requires 'value'")
            result[key] = copy.deepcopy(op_obj['value'])

        elif op_type == 'replace':
            if 'value' not in op_obj:
                raise ValueError("'replace' operation requires 'value'")
            if key not in result:
                raise ValueError(
                    f"Key {key!r} does not exist; cannot 'replace'"
                )
            result[key] = copy.deepcopy(op_obj['value'])

        elif op_type == 'remove':
            if key not in result:
                raise ValueError(
                    f"Key {key!r} does not exist; cannot 'remove'"
                )
            del result[key]

        elif op_type == 'test':
            if 'value' not in op_obj:
                raise ValueError("'test' operation requires 'value'")
            if key not in result:
                raise ValueError(
                    f"Key {key!r} does not exist; 'test' failed"
                )
            if result[key] != op_obj['value']:
                raise ValueError(
                    f"Test failed for key {key!r}: "
                    f"expected {op_obj['value']!r}, got {result[key]!r}"
                )

    return result
