from collections import deque


def dependency_levels(graph):
    """Return tasks grouped by earliest runnable parallel batch.

    Args:
        graph: dict mapping task name (str) -> list of prerequisite task names (str).

    Returns:
        List of sorted lists; each inner list is a batch of tasks that can run
        in parallel once all earlier batches have completed.

    Raises:
        ValueError: if the dependency graph contains a cycle (including self-cycles).
    """
    if not graph:
        return []

    # Collect all task names (keys + prerequisite-only names)
    all_tasks = set(graph.keys())
    for prereqs in graph.values():
        all_tasks.update(prereqs)

    # Build deduplicated prerequisite map without mutating the input
    prereq_map = {}
    for task in all_tasks:
        if task in graph:
            prereq_map[task] = list(set(graph[task]))
        else:
            prereq_map[task] = []

    # Compute in-degree (number of prerequisites) for each task
    in_degree = {task: len(prereq_map[task]) for task in all_tasks}

    # Build reverse adjacency: prerequisite -> tasks that depend on it
    dependents = {task: [] for task in all_tasks}
    for task in all_tasks:
        for p in prereq_map[task]:
            dependents[p].append(task)

    # Kahn's algorithm by levels (BFS)
    current_level = sorted(t for t in all_tasks if in_degree[t] == 0)
    result = []
    processed = 0

    while current_level:
        result.append(current_level)
        processed += len(current_level)
        next_level = set()
        for task in current_level:
            for dep in dependents[task]:
                in_degree[dep] -= 1
                if in_degree[dep] == 0:
                    next_level.add(dep)
        current_level = sorted(next_level)

    if processed != len(all_tasks):
        raise ValueError("Cycle detected in dependency graph")

    return result
