def find_all(text, pattern):
    """Return starting indices of every occurrence of pattern in text (including overlaps).

    Empty pattern matches all len(text)+1 boundaries.
    Runs in O(len(text) + len(pattern)) time using KMP.
    Works on Python str (Unicode code points).
    """
    n = len(text)
    m = len(pattern)

    if m == 0:
        return list(range(n + 1))

    # --- Build the KMP failure (prefix) table for pattern ---
    fail = [0] * m
    k = 0
    for i in range(1, m):
        while k > 0 and pattern[k] != pattern[i]:
            k = fail[k - 1]
        if pattern[k] == pattern[i]:
            k += 1
        fail[i] = k

    # --- KMP search over text ---
    result = []
    k = 0
    for i in range(n):
        while k > 0 and text[i] != pattern[k]:
            k = fail[k - 1]
        if text[i] == pattern[k]:
            k += 1
        if k == m:
            result.append(i - m + 1)
            k = fail[k - 1]  # allows overlapping matches

    return result
